            {"name": "Campanha acima da expectativa?", "rule": "vitórias × vitórias esperadas pelo overall das unidades · margem do jogo × esperada (mando 2,5) · surpresa = tanh(...)", "onFalse": "contribuição negativa × rigor da diretoria por dificuldade"},
            {"name": "Delta dentro dos limites?", "rule": "EMA (memória 6 semanas, temporada curta) · deltaClub e deltaLeague em [−10, +6]", "onFalse": "clamp e [0, 100]"},
            {"name": "Zona crítica com histerese?", "rule": "moraleClub < 30 → weeksUnderCritical++ · ≥ 35 zera · 30–44 Atenção", "onFalse": "Confortável (≥ 45)"},
            {"name": "Demitir?", "rule": "weeksUnderCritical ≥ paciência (EASY 4 · NORMAL 3 · HARD 2 · LEGEND 2) · nunca durante a semana de jogo", "onFalse": "aviso da diretoria"},
