            {"name": "Moral entra no RF42?", "rule": "ContextFactors.forMatch(moralClub, moralLiga, moralJogador) → ±3 % nas chances por unidade · performanceModifier até ±5 % por jogador", "onFalse": "neutro (moral 50)"},
