                    {"actor": "Backend", "do": "Defesa escolhe pacote (4-3, 3-4, nickel, dime, goal line), cobertura (Cover 0–6, man ou zona), blitz e espião"},
                    {"actor": "Backend", "if": "falta antes do snap?", "yes": [{"actor": "Backend", "do": "False start, offside ou encroachment · marca jardas · repete a descida"}],
                     "no": [
                        {"actor": "Backend", "do": "Snap · confrontos: OL × DL (pressão, sack), rota × cobertura (alvo, completo, INT), corredor × tackle (jardas, YAC, fumble) · fadiga, moral, clima"},
                        {"actor": "Backend", "if": "turnover na jogada?", "yes": [{"actor": "Backend", "do": "INT ou fumble perdido · retorno · troca de posse"}]},
                        {"actor": "Backend", "if": "falta durante a jogada?", "yes": [
                            {"actor": "Backend", "if": "aceitar a falta?", "yes": [{"actor": "Backend", "do": "Aplica jardas, 1ª descida automática ou perda de descida"}], "no": [{"actor": "Backend", "do": "Vale o resultado da jogada"}]},
                        ]},
                        {"actor": "Backend", "if": "primeira descida?", "yes": [{"actor": "Backend", "do": "1st & 10 (ou & goal)"}], "no": [{"actor": "Backend", "do": "down + 1 · turnover on downs se era a 4ª"}]},
                     ]},
                    {"actor": "Backend", "if": "pontuou?", "yes": [{"actor": "Backend", "do": "TD → PAT da 15 ou 2 pontos (decisão) · FG 3 · safety 2 + free kick · kickoff"}]},
                    {"actor": "Backend", "if": "relógio para?", "yes": [{"actor": "Backend", "do": "Relógio parado · play clock 40 s ou 25 s"}], "no": [{"actor": "Backend", "do": "Consome tempo pelo ritmo (hurry-up, normal, segurar a bola) · spike e kneel"}]},
                    {"actor": "Backend", "do": "Lesão pela exposição (Injury) · PlayEvent com texto PT-BR · Drive atualizado · box score"},
